                comp = []
                while stack:
                    x, y = stack.pop()
                    comp.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        p = (x + dx, y + dy)
                        if (0 <= p[0] < h and 0 <= p[1] < w
                                and grid[p[0]][p[1]] == color and p not in seen):
                            seen.add(p)
                            stack.append(p)
                result.append(comp)
        return result

    def shape(comp):
        mr = min(r for r, c in comp)
        mc = min(c for r, c in comp)
        return frozenset((r - mr, c - mc) for r, c in comp)

    templates = {}
    for color in range(2, 10):
        for comp in components(color):
            templates.setdefault(shape(comp), color)

